$canEdit=in_array($_SESSION['rol']??'', ['gerente','inventario'], true);
$notice=$error=''; $dir=__DIR__.'/../assets/img/productos/'; $web='assets/img/productos/';

ob_start(static function (string $output): string {
  return strtr($output, [
    'ÃƒÂ¡' => 'á', 'ÃƒÂ©' => 'é', 'ÃƒÂ­' => 'í',
    'ÃƒÂ³' => 'ó', 'ÃƒÂº' => 'ú', 'ÃƒÂ±' => 'ñ',
    'ÃƒÂ' => 'Á', 'ÃƒÂ‰' => 'É', 'ÃƒÂ' => 'Í',
    'ÃƒÂ“' => 'Ó', 'ÃƒÂš' => 'Ú', 'Ãƒâ€˜' => 'Ñ',
    'Ã‚Â¿' => '¿', 'Ã‚Â¡' => '¡',
  ]);
});

foreach ([
 'PRO_descripcion' => 'TEXT NULL AFTER PRO_nombre_producto',
 'PRO_marca' => 'VARCHAR(100) NULL AFTER PRO_descripcion',
 'PRO_imagen_url' => 'VARCHAR(255) NULL AFTER PRO_marca',
 'PRO_proveedor' => "VARCHAR(150) NOT NULL DEFAULT 'Proveedor por asignar' AFTER PRO_imagen_url",
] as $column => $definition) {
 $columnCheck=$db->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='productos' AND column_name=?");
 $columnCheck->execute([$column]);
 if(!(bool)$columnCheck->fetchColumn()) $db->exec("ALTER TABLE productos ADD COLUMN `$column` $definition");
}

if($_SERVER['REQUEST_METHOD']==='POST' && $canEdit){
 csrf_verify();
 $action=$_POST['product_action']??''; $code=(int)($_POST['codigo']??0);
 try{
  if(in_array($action,['create','update'],true)){
    $name=trim($_POST['nombre_producto']??''); $description=trim($_POST['descripcion']??''); $brand=trim($_POST['marca']??''); $supplier=trim($_POST['proveedor']??'Proveedor por asignar'); $category=trim($_POST['categoria']??'Abrasivos');
   $price=filter_var($_POST['precio']??null,FILTER_VALIDATE_FLOAT); $stock=filter_var($_POST['stock']??null,FILTER_VALIDATE_INT); $minimum=filter_var($_POST['stock_minimo']??null,FILTER_VALIDATE_INT);
   if($name===''||$price===false||$price<0||$stock===false||$stock<0||$minimum===false||$minimum<0) throw new RuntimeException('Completa correctamente nombre, precio y existencias.');
   $image=trim($_POST['imagen_actual']??'');
   if(!empty($_FILES['imagen']['name'])){$file=$_FILES['imagen'];$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if($file['error']!==UPLOAD_ERR_OK||$file['size']>3145728||!isset($types[$mime]))throw new RuntimeException('La imagen debe ser JPG, PNG o WEBP y pesar mÃƒÂ¡ximo 3 MB.');$fileName=bin2hex(random_bytes(12)).'.'.$types[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.$fileName))throw new RuntimeException('No fue posible guardar la imagen.');$image=$web.$fileName;}
  if($action==='create'){$categoryStmt=$db->prepare('SELECT id_categoria FROM categoria WHERE nombre_categoria=? LIMIT 1');$categoryStmt->execute([$category]);$categoryId=$categoryStmt->fetchColumn();if(!$categoryId){$categoryStmt=$db->prepare('INSERT INTO categoria (nombre_categoria,descripcion) VALUES (?,?)');$categoryStmt->execute([$category,'CategorÃƒÂ­a de productos']);$categoryId=$db->lastInsertId();}$code=(int)$db->query('SELECT COALESCE(MAX(PRO_codigo),0)+1 FROM productos')->fetchColumn();$stmt=$db->prepare('INSERT INTO productos (PRO_codigo,PRO_nombre_producto,PRO_descripcion,PRO_marca,PRO_imagen_url,PRO_precio_unitario,PRO_stock_actual,PRO_stock_minimo,PRO_cantidad_disponible,id_categoria,id_tipo_material,PRO_costo_base) VALUES (?,?,?,?,?,?,?,?,?,?,1,?)');$stmt->execute([$code,$name,$description,$brand,$image,$price,$stock,$minimum,$stock,$categoryId,$price]);$catalogStmt=$db->prepare('INSERT INTO catalogo (CAT_id_producto,GER_documento_identidad,CAT_nombre_producto,CAT_tipo_material,CAT_unidad_empaque,CAT_medidas,CAT_precio_unitario,CAT_foto_empaque) VALUES (?,?,?,?,?,?,?,?)');$catalogStmt->execute([$code,(int)($_SESSION['user']['documento_id']??0),$name,'Abrasivo','Unidad','',$price,$image?:null]);$notice='Producto creado correctamente.';}
   else{$stmt=$db->prepare('UPDATE productos SET PRO_nombre_producto=?,PRO_descripcion=?,PRO_marca=?,PRO_imagen_url=?,PRO_precio_unitario=?,PRO_stock_actual=?,PRO_stock_minimo=?,PRO_cantidad_disponible=? WHERE PRO_codigo=?');$stmt->execute([$name,$description,$brand,$image,$price,$stock,$minimum,$stock,$code]);$catalogStmt=$db->prepare('UPDATE catalogo SET CAT_nombre_producto=?,CAT_precio_unitario=?,CAT_foto_empaque=? WHERE CAT_id_producto=?');$catalogStmt->execute([$name,$price,$image?:null,$code]);$notice='Producto actualizado correctamente.';}
  }elseif($action==='delete'){$check=$db->prepare('SELECT PRO_codigo FROM productos WHERE PRO_codigo=? AND deleted_at IS NULL');$check->execute([$code]);if(!$check->fetchColumn())throw new RuntimeException('Producto no encontrado.');$stmt=$db->prepare('UPDATE productos SET deleted_at=NOW() WHERE PRO_codigo=?');$stmt->execute([$code]);$notice='Producto eliminado correctamente.';}
 }catch(Throwable $e){$error=$e->getMessage();}
}
$search=trim($_GET['q']??'');$searchWhere=$search!==''?" AND (PRO_nombre_producto LIKE ? OR PRO_marca LIKE ? OR PRO_descripcion LIKE ?)":'';$searchParams=$search!==''?["%$search%","%$search%","%$search%"]:[];$productsSql='SELECT PRO_codigo,PRO_nombre_producto,PRO_descripcion,PRO_marca,PRO_imagen_url,PRO_precio_unitario,PRO_stock_actual,PRO_stock_minimo FROM productos WHERE deleted_at IS NULL'.$searchWhere.' ORDER BY PRO_codigo DESC';$productsStmt=$db->prepare($productsSql);$productsStmt->execute($searchParams);$products=$productsStmt->fetchAll(PDO::FETCH_ASSOC);
?>
