uct()"><i class="fas fa-plus me-1"></i>Agregar producto</button><?php endif;?></div><?php if($notice):?><div class="alert alert-success"><?php echo htmlspecialchars($notice,ENT_QUOTES,'UTF-8');?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo htmlspecialchars($error,ENT_QUOTES,'UTF-8');?></div><?php endif;?><div class="card mb-4"><div class="card-header d-flex justify-content-between align-items-center"><span><i class="fas fa-boxes me-1"></i>CatÃƒÂ¡logo de productos</span><form method="GET" action="index.php" class="d-inline-flex gap-1 mb-0"><input type="hidden" name="action" value="inventario"><input type="text" name="q" class="form-control form-control-sm" style="max-width:220px" placeholder="Buscar producto o marca..." value="<?php echo htmlspecialchars($search,ENT_QUOTES);?>"><button type="submit" class="btn btn-sm btn-outline-primary"><i class="fas fa-search"></i></button><?php if($search!==''):?><a href="index.php?action=inventario" class="btn btn-sm btn-outline-secondary"><i class="fas fa-times"></i></a><?php endif;?></form></div><div class="card-body table-responsive"><table id="productsTable" class="table table-striped align-middle"><thead><tr><th>Foto</th><th>Producto</th><th>DescripciÃƒÂ³n</th><th>Precio</th><th>Stock</th><th>Estado</th><?php if($canEdit):?><th>Acciones</th><?php endif;?></tr></thead><tbody><?php foreach($products as $p):$stock=(int)$p['PRO_stock_actual'];$min=(int)$p['PRO_stock_minimo'];$state=$stock===0?'Agotado':($stock<=$min?'Stock bajo':'Disponible');?><tr><td><?php if($p['PRO_imagen_url']):?><img class="product-image" src="<?php echo htmlspecialchars($p['PRO_imagen_url'],ENT_QUOTES,'UTF-8');?>" alt="Producto"><?php else:?><div class="product-placeholder"><i class="fas fa-image"></i></div><?php endif;?></td><td><strong><?php echo htmlspecialchars($p['PRO_nombre_producto'],ENT_QUOTES,'UTF-8');?></strong><br><small class="text-muted"><?php echo htmlspecialchars($p['PRO_marca']??'',ENT_QUOTES,'UTF-8');?></small></td><td><?php echo htmlspecialchars($p['PRO_descripcion']??'Sin descripciÃƒÂ³n',ENT_QUOTES,'UTF-8');?></td><td>$ <?php echo number_format((float)$p['PRO_precio_unitario'],0,',','.');?></td><td><?php echo $stock;?> <small class="text-muted">/ mÃƒÂ­n. <?php echo $min;?></small></td><td><span class="badge <?php echo $stock===0?'bg-danger':($stock<=$min?'bg-warning text-dark':'bg-success');?>"><?php echo $state;?></span></td><?php if($canEdit):?><td><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#productModal" onclick='editProduct(<?php echo json_encode($p,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP);?>)'><i class="fas fa-edit"></i></button><form method="post" class="d-inline" onsubmit="return confirm('Ã‚Â¿Eliminar este producto?')"><?php echo csrf_field();?><input type="hidden" name="product_action" value="delete"><input type="hidden" name="codigo" value="<?php echo (int)$p['PRO_codigo'];?>"><button class="btn btn-sm btn-outline-danger"><i class="fas fa-trash"></i></button></form></td><?php endif;?></tr><?php endforeach;?><?php if(!$products):?><tr><td colspan="7" class="text-center text-muted">No hay productos registrados.</td></tr><?php endif;?></tbody></table></div></div></div></main></div></div><?php if($canEdit):?><div class="modal fade" id="productModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" enctype="multipart/form-data"><?php echo csrf_field();?><div class="modal-header"><h5 class="modal-title" id="modalTitle">Agregar producto</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="product_action" id="productAction" value="create"><input type="hidden" name="codigo" id="productCode"><input type="hidden" name="imagen_actual" id="currentImage"><div class="row g-3"><div class="col-md-8"><label class="form-label">Nombre *</label><input class="form-control" name="nombre_producto" id="productName" required></div><div class="col-md-4"><label class="form-label">Marca</label><input class="form-control" name="marca" id="productBrand"></div><div class="col-12"><label class="form-label">DescripciÃƒÂ³n</label><textarea class="form-control" name="descripcion" id="productDescription" rows="3"></textarea></div><div class="col-md-4"><label class="form-label">Precio *</label><input class="form-control" type="number" min="0" step="0.01" name="precio" id="productPrice" required></div><div class="col-md-4"><label class="form-label">Stock *</label><input class="form-control" type="number" min="0" name="stock" id="productStock" required></div><div class="col-md-4"><label class="form-label">Stock mÃƒÂ­nimo</label><input class="form-control" type="number" min="0" name="stock_minimo" id="productMinimum" value="0"></div><div class="col-12"><label class="form-label">Foto del producto</label><input class="form-control" type="file" name="imagen" accept="image/jpeg,image/png,image/webp"><div class="form-text">JPG, PNG o WEBP, mÃƒÂ¡ximo 3 MB.</div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary"><i class="fas fa-save me-1"></i>Guardar producto</button></div></form></div></div></div><?php endif;?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.2.3/dist/js/bootstrap.bundle.min.js"></script><script>function newProduct(){const f=document.querySelector('#productModal form');f.reset();document.getElementById('modalTitle').textContent='Agregar producto';document.getElementById('productAction').value='create';document.getElementById('productCode').value='';document.getElementById('currentImage').value='';}function editProduct(p){document.getElementById('modalTitle').textContent='Editar producto';document.getElementById('productAction').value='update';document.getElementById('productCode').value=p.PRO_codigo;document.getElementById('currentImage').value=p.PRO_imagen_url||'';document.getElementById('productName').value=p.PRO_nombre_producto||'';document.getElementById('productBrand').value=p.PRO_marca||'';document.getElementById('productDescription').value=p.PRO_descripcion||'';document.getElementById('productPrice').value=p.PRO_precio_unitario||0;document.getElementById('productStock').value=p.PRO_stock_actual||0;document.getElementById('productMinimum').value=p.PRO_stock_minimo||0;}</script></body></html>
